 @Implements(android.webkit.WebView.class) public static class EpubWeb extends ShadowWebView {@Implementation protected float getScale(){return 1f;}}
 static File source;ActivityController<ReaderActivity> controller;ReaderActivity a;
 public static class Provider extends ContentProvider{public boolean onCreate(){return true;}public String getType(Uri u){return "application/epub+zip";}public ParcelFileDescriptor openFile(Uri u,String m)throws FileNotFoundException{return ParcelFileDescriptor.open(source,ParcelFileDescriptor.MODE_READ_ONLY);}public Cursor query(Uri u,String[] p,String s,String[] args,String o){return null;}public Uri insert(Uri u,ContentValues v){return null;}public int update(Uri u,ContentValues v,String s,String[] args){return 0;}public int delete(Uri u,String s,String[] args){return 0;}}
 @Before public void setup()throws Exception{Application app=RuntimeEnvironment.getApplication();source=new File(app.getCacheDir(),"pages.epub");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(source))){ChapterExportTest.entry(zip,"META-INF/container.xml","<container><rootfiles><rootfile full-path='book.opf'/></rootfiles></container>");ChapterExportTest.entry(zip,"book.opf","<package><manifest><item id='a' href='a.html' media-type='application/xhtml+xml'/><item id='b' href='b.html' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='a'/><itemref idref='b'/></spine></package>");StringBuilder text=new StringBuilder("<html><head><link rel='stylesheet' href='style.css' /></head><body>");for(int i=0;i<180;i++)text.append("<p>Uma passagem de leitura com texto suficientemente longo para várias páginas. Linha ").append(i).append(".</p>");text.append("</body></html>");ChapterExportTest.entry(zip,"a.html",text.toString());ChapterExportTest.entry(zip,"style.css","p { color: #1270aa; font-size: 19px; }");ChapterExportTest.entry(zip,"b.html","<html><body><p>Segundo capítulo.</p></body></html>");}Provider provider=new Provider();ProviderInfo info=new ProviderInfo();info.authority="seeky.turn.test";provider.attachInfo(app,info);ShadowContentResolver.registerProviderInternal(info.authority,provider);controller=Robolectric.buildActivity(ReaderActivity.class,new Intent(app,ReaderActivity.class).setDataAndType(Uri.parse("content://seeky.turn.test/book.epub"),"application/epub+zip").putExtra("name","Livro.epub"));a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);a.getSharedPreferences("seeky",0).edit().putBoolean("reader_original_content://seeky.turn.test/book.epub",false).apply();controller.create().start().resume().visible();drain();layout();}
 void layout(){a.root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(720,View.MeasureSpec.EXACTLY));a.root.layout(0,0,360,720);shadowOf(Looper.getMainLooper()).idle();}
 void drain()throws Exception{for(int i=0;i<4;i++){a.worker.submit(()->{}).get(15,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 @After public void close(){if(controller!=null)controller.pause().stop().destroy();}
 void settle(){for(int frame=0;frame<32;frame++){shadowOf(Looper.getMainLooper()).idleFor(16,TimeUnit.MILLISECONDS);a.bookScroll.computeScroll();}}
 void swipe(float x1,float y1,float x2,float y2,long duration)throws Exception{long t=SystemClock.uptimeMillis();for(int i=0;i<=5;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==5?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;MotionEvent event=MotionEvent.obtain(t,SystemClock.uptimeMillis(),action,x1+(x2-x1)*i/5f,y1+(y2-y1)*i/5f,0);try{a.bookScroll.dispatchTouchEvent(event);}finally{event.recycle();}shadowOf(Looper.getMainLooper()).idleFor(duration/5,TimeUnit.MILLISECONDS);}settle();drain();layout();}
 @Test public void originalEpubRetainsMarkupAndStylesWithScriptsAndRemoteRequestsBlocked()throws Exception{a.original.show();drain();assertTrue(a.original.active);assertSame(a.body,a.original.view.getParent());assertTrue(a.original.view.getSettings().getJavaScriptEnabled());assertTrue(a.original.resource(Uri.parse(a.original.expectedUrl)).getResponseHeaders().get("Content-Security-Policy").contains("script-src 'none'"));assertFalse(a.original.view.getSettings().getAllowFileAccess());android.webkit.WebResourceResponse css=a.original.resource(Uri.parse("https://seeky-document.invalid/book/style.css"));byte[] content=new byte[128];int count=css.getData().read(content);css.getData().close();assertTrue(new String(content,0,count,"UTF-8").contains("font-size: 19px"));android.webkit.WebResourceResponse denied=a.original.resource(Uri.parse("https://outside.invalid/secret"));assertEquals(-1,denied.getData().read());a.original.textMode();assertSame(a.body,a.bookScroll.getParent());}
 @Test public void originalEpubLayoutControlsApplyWithoutFlatteningTheBookAndPersist()throws Exception{
  byte[] before=Files.readAllBytes(source.toPath());a.original.show();drain();a.chrome.textSettings();android.app.Dialog dialog=ShadowDialog.getLatestDialog();java.util.List<android.widget.SeekBar> sliders=new java.util.ArrayList<>();collectSliders(dialog.getWindow().getDecorView(),sliders);assertEquals(3,sliders.size());userProgress(sliders.get(0),75);userProgress(sliders.get(1),20);userProgress(sliders.get(2),60);android.view.View group=VoiceToolsTest.findText(dialog.getWindow().getDecorView(),"Alinhamento");ChoiceSpinner align=findChoice(dialog.getWindow().getDecorView());assertNotNull(align);align.setSelection(2);shadowOf(Looper.getMainLooper()).idleFor(250,TimeUnit.MILLISECONDS);drain();assertTrue(a.original.active);assertSame(a.body,a.original.view.getParent());assertEquals(150,a.original.view.getSettings().getTextZoom());assertFalse(a.original.view.getSettings().getUseWideViewPort());assertTrue(a.original.view.getSettings().getJavaScriptEnabled());assertEquals(28,a.original.options().margin);assertEquals(160,a.original.options().spacing);assertEquals(2,a.original.options().align);String css=read(a.original.resource(Uri.parse(EpubLayout.CSS_URL)).getData());assertTrue(css.contains("28px"));assertTrue(css.contains("line-height:1.6"));assertTrue(css.contains("text-align:justify"));assertArrayEquals(before,Files.readAllBytes(source.toPath()));dialog.dismiss();
  controller.pause().stop().destroy();controller=Robolectric.buildActivity(ReaderActivity.class,new Intent(RuntimeEnvironment.getApplication(),ReaderActivity.class).setDataAndType(Uri.parse("content://seeky.turn.test/book.epub"),"application/epub+zip").putExtra("name","Livro.epub"));a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create().start().resume().visible();drain();layout();assertTrue(a.original.active);assertEquals(150,a.original.view.getSettings().getTextZoom());assertEquals(28,a.original.options().margin);assertEquals(160,a.original.options().spacing);a.original.resetEpub();shadowOf(Looper.getMainLooper()).idleFor(250,TimeUnit.MILLISECONDS);drain();assertEquals(100,a.original.view.getSettings().getTextZoom());assertEquals(0,a.original.options().spacing);assertEquals(0,a.original.options().align);
 }
 @Test public void organizeOpensReadingLayoutDirectlyInOriginalEpub()throws Exception{a.original.show();drain();a.chrome.organize();android.app.Dialog menu=ShadowDialog.getLatestDialog();View action=findDescription(menu.getWindow().getDecorView(),"Ajustar leitura");assertNotNull(action);action.performClick();android.app.Dialog settings=ShadowDialog.getLatestDialog();assertNotSame(menu,settings);assertNotNull(VoiceToolsTest.findText(settings.getWindow().getDecorView(),"Adaptar à largura do ecrã"));assertNotNull(VoiceToolsTest.findText(settings.getWindow().getDecorView(),"TAMANHO DO TEXTO"));assertTrue(a.original.active);assertSame(a.body,a.original.view.getParent());settings.dismiss();}
 static String read(InputStream in)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];for(int n;(n=input.read(b))!=-1;)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}}
 static void collectSliders(View v,java.util.List<android.widget.SeekBar> out){if(v instanceof android.widget.SeekBar)out.add((android.widget.SeekBar)v);if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int n=0;n<g.getChildCount();n++)collectSliders(g.getChildAt(n),out);}}
 static ChoiceSpinner findChoice(View v){if(v instanceof ChoiceSpinner)return (ChoiceSpinner)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int n=0;n<g.getChildCount();n++){ChoiceSpinner found=findChoice(g.getChildAt(n));if(found!=null)return found;}}return null;}
 static View findDescription(View v,String text){if(text.equals(v.getContentDescription()))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int n=0;n<g.getChildCount();n++){View found=findDescription(g.getChildAt(n),text);if(found!=null)return found;}}return null;}
 static void userProgress(android.widget.SeekBar bar,int value){bar.setProgress(value);org.robolectric.util.ReflectionHelpers.<android.widget.SeekBar.OnSeekBarChangeListener>getField(bar,"mOnSeekBarChangeListener").onProgressChanged(bar,value,true);}
 @Test public void horizontalSwipeAdvancesViewportWithoutSkippingTheChapter()throws Exception{assertTrue(a.bookScroll instanceof ReaderScrollView);assertEquals(0,a.chapter);int first=a.bookScroll.getScrollY();swipe(300,100,50,110,180);assertTrue("horizontal turn advances screen",a.bookScroll.getScrollY()>first);assertEquals(0,a.chapter);int next=a.bookScroll.getScrollY();swipe(50,100,300,105,180);assertTrue("reverse page must go back: "+next+" -> "+a.bookScroll.getScrollY(),a.bookScroll.getScrollY()<next);}
 @Test public void chapterBoundaryOpensNextAndReverseReturnsToEndOfPrevious()throws Exception{a.bookScroll.scrollTo(0,Integer.MAX_VALUE);a.chrome.turn(1);drain();layout();assertEquals(1,a.chapter);assertEquals(0,a.bookScroll.getScrollY());a.chrome.turn(-1);drain();layout();shadowOf(Looper.getMainLooper()).idle();layout();assertEquals(0,a.chapter);assertTrue("return lands at previous chapter end",a.bookScroll.getScrollY()>0);}
 @Test public void selectedTextDoesNotTurnPage()throws Exception{Selection.setSelection((Spannable)a.bookText.getText(),0,8);int first=a.bookScroll.getScrollY();swipe(300,100,50,100,180);assertTrue(Math.abs(a.bookScroll.getScrollY()-first)<=a.bookText.getLineHeight());assertEquals(0,a.chapter);}
 @Test public void verticalScrollKeepsTheSameChapter()throws Exception{swipe(180,280,185,60,180);assertEquals(0,a.chapter);assertTrue(a.bookScroll.getScrollY()>0);}
 @Test public void buttonsUseSameViewportTurningAndSavePosition()throws Exception{a.chrome.turn(1);settle();layout();a.positions.flush();assertTrue(a.bookScroll.getScrollY()>a.bookScroll.getHeight()/2);assertEquals(a.bookScroll.getScrollY(),a.getSharedPreferences("seeky",0).getInt("reader_scroll_"+a.uri+":0",-1));} @Test public void circularButtonReopensTheSameBookAtSavedScrollPosition()throws Exception{a.bookScroll.scrollTo(0,600);int y=a.bookScroll.getScrollY();assertTrue(y>0);controller.pause().stop().destroy();controller=null;LastReading.Saved saved=LastReading.get(RuntimeEnvironment.getApplication());assertEquals("content://seeky.turn.test/book.epub",saved.uri);MainActivity main=Robolectric.buildActivity(MainActivity.class).get();main.setTheme(android.R.style.Theme_Material_NoActionBar);main.prefs=main.getSharedPreferences("seeky",0);main.colors();main.tab="Livros";main.body=main.column();main.setContentView(main.body);main.studies=new StudyHub(main);main.books=new BookLibrary(main);Intent resume;try{main.books.show();for(int i=0;i<2;i++){main.books.worker.submit(()->{}).get(10,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}assertNotNull(main.books.resumeButton);assertEquals(main.dp(60),main.books.resumeButton.getLayoutParams().width);main.books.resumeButton.performClick();main.books.worker.submit(()->{}).get(10,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();resume=shadowOf(main).getNextStartedActivity();assertNotNull(resume);assertEquals(saved.uri,resume.getData().toString());assertFalse(resume.hasExtra("study_segment"));}finally{main.books.close();main.studies.close();main.dead=true;main.worker.shutdown();main.finder.shutdown();main.searchJobs.close();}controller=Robolectric.buildActivity(ReaderActivity.class,resume);a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create().start().resume().visible();drain();layout();assertEquals(0,a.chapter);assertEquals("tools.loading="+a.tools.loading+" textRequested="+a.bookText.isLayoutRequested()+" scrollRequested="+a.bookScroll.isLayoutRequested()+" pendingOffset="+a.tools.pendingOffset+" serial="+a.scrollRestoreSerial,y,a.bookScroll.getScrollY());}
 @Test public void lastReadingKeepsTheSelectedChapterWithoutReturningToFirst()throws Exception{a.chapter(1);drain();layout();assertEquals(1,a.chapter);controller.pause().stop().destroy();controller=null;Intent resume=LastReading.get(RuntimeEnvironment.getApplication()).intent(RuntimeEnvironment.getApplication());controller=Robolectric.buildActivity(ReaderActivity.class,resume);a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create().start().resume().visible();drain();layout();assertEquals(1,a.chapter);}

